CREATE TABLE account (
 account_id INT IDENTITY PRIMARY KEY, email NVARCHAR(254) NOT NULL UNIQUE, full_name NVARCHAR(120) NOT NULL,
 password_hash VARCHAR(300) NOT NULL, role VARCHAR(12) NOT NULL CHECK(role IN ('STUDENT','TEACHER','MANAGER')),
 status VARCHAR(30) NOT NULL DEFAULT 'PENDING_VERIFICATION' CHECK(status IN ('PENDING_VERIFICATION','PENDING_APPROVAL','ACTIVE','LOCKED')),
 email_verified_at DATETIME2, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
);
CREATE TABLE student(student_id INT IDENTITY PRIMARY KEY,account_id INT NOT NULL UNIQUE REFERENCES account(account_id),phone NVARCHAR(30),date_of_birth DATE);
CREATE TABLE teacher(teacher_id INT IDENTITY PRIMARY KEY,account_id INT NOT NULL UNIQUE REFERENCES account(account_id),phone NVARCHAR(30));
CREATE TABLE account_permission(account_id INT REFERENCES account(account_id),permission_code VARCHAR(60),allowed BIT NOT NULL,PRIMARY KEY(account_id,permission_code));
CREATE TABLE account_token(token_id INT IDENTITY PRIMARY KEY,account_id INT NOT NULL REFERENCES account(account_id),token_hash VARCHAR(64) NOT NULL UNIQUE,purpose VARCHAR(30) NOT NULL,payload NVARCHAR(MAX),attempts INT NOT NULL DEFAULT 0,expires_at DATETIME2 NOT NULL,consumed_at DATETIME2);
CREATE TABLE login_session(session_id INT IDENTITY PRIMARY KEY,account_id INT NOT NULL REFERENCES account(account_id),token_hash VARCHAR(64) NOT NULL UNIQUE,csrf_token VARCHAR(80) NOT NULL,expires_at DATETIME2 NOT NULL);
CREATE TABLE parent_contact(parent_id INT IDENTITY PRIMARY KEY,student_id INT NOT NULL REFERENCES student(student_id),name NVARCHAR(120),email NVARCHAR(254) NOT NULL,consent BIT NOT NULL DEFAULT 0,consent_at DATETIME2,UNIQUE(student_id,email));
CREATE TABLE course(course_id INT IDENTITY PRIMARY KEY,name NVARCHAR(200) NOT NULL,program VARCHAR(10) NOT NULL CHECK(program IN ('IELTS','SAT')),level NVARCHAR(60),description NVARCHAR(MAX),target_min DECIMAL(8,2),target_max DECIMAL(8,2),status VARCHAR(15) NOT NULL DEFAULT 'ACTIVE',created_by INT REFERENCES account(account_id),row_version ROWVERSION,CHECK(target_min IS NULL OR target_max IS NULL OR target_min<=target_max));
CREATE TABLE class_group(class_id INT IDENTITY PRIMARY KEY,course_id INT NOT NULL REFERENCES course(course_id),code NVARCHAR(60) NOT NULL UNIQUE,format VARCHAR(15) NOT NULL CHECK(format IN ('GROUP','INDIVIDUAL','SC')),starts_at DATETIME2 NOT NULL,ends_at DATETIME2 NOT NULL,tuition_amount DECIMAL(18,2) NOT NULL CHECK(tuition_amount>=0),currency VARCHAR(3) NOT NULL DEFAULT 'VND',status VARCHAR(15) NOT NULL DEFAULT 'OPEN',CHECK(ends_at>starts_at));
CREATE TABLE class_teacher(class_id INT REFERENCES class_group(class_id),teacher_id INT REFERENCES teacher(teacher_id),PRIMARY KEY(class_id,teacher_id));
CREATE TABLE enrollment(enrollment_id INT IDENTITY PRIMARY KEY,student_id INT NOT NULL REFERENCES student(student_id),class_id INT NOT NULL REFERENCES class_group(class_id),status VARCHAR(25) NOT NULL DEFAULT 'PENDING_PAYMENT',payment_status VARCHAR(15) NOT NULL DEFAULT 'UNPAID',approved BIT NOT NULL DEFAULT 0,approved_by INT REFERENCES account(account_id),fee_snapshot DECIMAL(18,2) NOT NULL,requested_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),success_at DATETIME2,UNIQUE(student_id,class_id));
CREATE TABLE tuition_payment(payment_id INT IDENTITY PRIMARY KEY,enrollment_id INT NOT NULL REFERENCES enrollment(enrollment_id),reference VARCHAR(40) NOT NULL UNIQUE,amount DECIMAL(18,2) NOT NULL CHECK(amount>=0),status VARCHAR(25) NOT NULL DEFAULT 'PENDING',provider VARCHAR(20) NOT NULL,provider_transaction_id VARCHAR(100),confirmed_by INT REFERENCES account(account_id),created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),paid_at DATETIME2);
CREATE UNIQUE INDEX uq_provider_tx ON tuition_payment(provider,provider_transaction_id) WHERE provider_transaction_id IS NOT NULL;
CREATE TABLE payment_event(event_id INT IDENTITY PRIMARY KEY,external_id VARCHAR(100) NOT NULL UNIQUE,payment_id INT REFERENCES tuition_payment(payment_id),status VARCHAR(25) NOT NULL,received_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),reason NVARCHAR(300));
CREATE TABLE file_asset(file_id INT IDENTITY PRIMARY KEY,storage_key VARCHAR(100) NOT NULL UNIQUE,original_name NVARCHAR(200),mime_type VARCHAR(100),byte_size INT NOT NULL,uploaded_by INT NOT NULL REFERENCES account(account_id),created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE course_material(material_id INT IDENTITY PRIMARY KEY,class_id INT NOT NULL REFERENCES class_group(class_id),title NVARCHAR(200) NOT NULL,description NVARCHAR(MAX),file_id INT REFERENCES file_asset(file_id),external_url NVARCHAR(2000),created_by INT NOT NULL REFERENCES account(account_id));
CREATE TABLE assignment(assignment_id INT IDENTITY PRIMARY KEY,class_id INT NOT NULL REFERENCES class_group(class_id),title NVARCHAR(200) NOT NULL,instructions NVARCHAR(MAX),task_type VARCHAR(30) NOT NULL,metric_code VARCHAR(30) NOT NULL DEFAULT 'PERCENT',max_score DECIMAL(8,2) NOT NULL DEFAULT 100 CHECK(max_score>0),criteria NVARCHAR(MAX),due_at DATETIME2 NOT NULL,status VARCHAR(15) NOT NULL DEFAULT 'PUBLISHED',created_by INT NOT NULL REFERENCES account(account_id));
CREATE TABLE assignment_submission(submission_id INT IDENTITY PRIMARY KEY,assignment_id INT NOT NULL REFERENCES assignment(assignment_id),student_id INT NOT NULL REFERENCES student(student_id),text_content NVARCHAR(MAX),external_url NVARCHAR(2000),file_id INT REFERENCES file_asset(file_id),submitted_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),score DECIMAL(8,2),feedback NVARCHAR(MAX),graded_by INT REFERENCES account(account_id),graded_at DATETIME2,status VARCHAR(15) NOT NULL DEFAULT 'SUBMITTED',UNIQUE(assignment_id,student_id));
CREATE TABLE assessment_score(score_id INT IDENTITY PRIMARY KEY,student_id INT NOT NULL REFERENCES student(student_id),class_id INT REFERENCES class_group(class_id),metric_code VARCHAR(30) NOT NULL,score_value DECIMAL(8,2) NOT NULL,max_value DECIMAL(8,2) NOT NULL,assessment_date DATETIME2 NOT NULL,label NVARCHAR(200),submission_id INT REFERENCES assignment_submission(submission_id),attempt_id INT NULL,created_by INT REFERENCES account(account_id),CHECK(score_value>=0 AND score_value<=max_value));
CREATE TABLE student_target(student_id INT REFERENCES student(student_id),metric_code VARCHAR(30),target_value DECIMAL(8,2) NOT NULL,PRIMARY KEY(student_id,metric_code));
CREATE TABLE schedule_event(event_id INT IDENTITY PRIMARY KEY,owner_id INT NOT NULL REFERENCES account(account_id),class_id INT REFERENCES class_group(class_id),assignment_id INT REFERENCES assignment(assignment_id),title NVARCHAR(200) NOT NULL,event_type VARCHAR(30) NOT NULL,starts_at DATETIME2 NOT NULL,ends_at DATETIME2 NOT NULL,reminder_at DATETIME2,reminder_queued BIT NOT NULL DEFAULT 0,row_version ROWVERSION,CHECK(ends_at>starts_at));
CREATE TABLE event_participant(event_id INT REFERENCES schedule_event(event_id),account_id INT REFERENCES account(account_id),PRIMARY KEY(event_id,account_id));
CREATE TABLE teaching_session(session_id INT IDENTITY PRIMARY KEY,event_id INT NOT NULL UNIQUE REFERENCES schedule_event(event_id),class_id INT NOT NULL REFERENCES class_group(class_id),teacher_id INT NOT NULL REFERENCES teacher(teacher_id),duration_minutes INT CHECK(duration_minutes>0),recorded_at DATETIME2,approval_status VARCHAR(15) NOT NULL DEFAULT 'PENDING',approved_by INT REFERENCES account(account_id),hourly_rate DECIMAL(18,2));
CREATE TABLE attendance(session_id INT REFERENCES teaching_session(session_id),student_id INT REFERENCES student(student_id),status VARCHAR(15) NOT NULL CHECK(status IN ('PRESENT','ABSENT','LATE','EXCUSED')),notes NVARCHAR(1000),PRIMARY KEY(session_id,student_id));
CREATE TABLE post_class_report(report_id INT IDENTITY PRIMARY KEY,session_id INT NOT NULL REFERENCES teaching_session(session_id),student_id INT NOT NULL REFERENCES student(student_id),participation NVARCHAR(1000),remarks NVARCHAR(MAX),recommendations NVARCHAR(MAX),report_version INT NOT NULL DEFAULT 1,submitted_by INT REFERENCES account(account_id),submitted_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UNIQUE(session_id,student_id));
CREATE TABLE email_outbox(email_id INT IDENTITY PRIMARY KEY,kind VARCHAR(30) NOT NULL,parent_id INT REFERENCES parent_contact(parent_id),recipient NVARCHAR(254) NOT NULL,subject NVARCHAR(200) NOT NULL,protected_payload NVARCHAR(MAX) NOT NULL,dedupe_key VARCHAR(160) NOT NULL UNIQUE,status VARCHAR(15) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),lease_until DATETIME2,last_error NVARCHAR(500),sent_at DATETIME2,provider_message_id NVARCHAR(300));
CREATE TABLE teacher_rate(rate_id INT IDENTITY PRIMARY KEY,teacher_id INT NOT NULL REFERENCES teacher(teacher_id),class_format VARCHAR(15) NOT NULL,hourly_rate DECIMAL(18,2) NOT NULL CHECK(hourly_rate>=0),valid_from DATE NOT NULL,valid_to DATE,CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE TABLE teacher_bonus(bonus_id INT IDENTITY PRIMARY KEY,teacher_id INT NOT NULL REFERENCES teacher(teacher_id),period CHAR(7) NOT NULL,amount DECIMAL(18,2) NOT NULL CHECK(amount>=0),reason NVARCHAR(500),approved BIT NOT NULL DEFAULT 0,created_by INT REFERENCES account(account_id));
CREATE TABLE practice_test(test_id INT IDENTITY PRIMARY KEY,class_id INT NOT NULL REFERENCES class_group(class_id),title NVARCHAR(200) NOT NULL,program VARCHAR(10) NOT NULL,description NVARCHAR(MAX),duration_minutes INT NOT NULL CHECK(duration_minutes BETWEEN 1 AND 600),status VARCHAR(15) NOT NULL DEFAULT 'DRAFT',created_by INT NOT NULL REFERENCES account(account_id));
CREATE TABLE test_question(question_id INT IDENTITY PRIMARY KEY,test_id INT NOT NULL REFERENCES practice_test(test_id),position INT NOT NULL,section_code VARCHAR(30) NOT NULL,question_type VARCHAR(15) NOT NULL CHECK(question_type IN ('MCQ','SHORT','WRITING','SPEAKING')),prompt NVARCHAR(MAX) NOT NULL,options_json NVARCHAR(MAX),answer_key NVARCHAR(MAX),points DECIMAL(8,2) NOT NULL CHECK(points>0),media_url NVARCHAR(2000),UNIQUE(test_id,position));
CREATE TABLE test_scale(test_id INT REFERENCES practice_test(test_id),section_code VARCHAR(30),raw_points DECIMAL(8,2),scaled_score DECIMAL(8,2) NOT NULL,max_score DECIMAL(8,2) NOT NULL,PRIMARY KEY(test_id,section_code,raw_points));
CREATE TABLE test_attempt(attempt_id INT IDENTITY PRIMARY KEY,test_id INT NOT NULL REFERENCES practice_test(test_id),student_id INT NOT NULL REFERENCES student(student_id),started_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),deadline_at DATETIME2 NOT NULL,submitted_at DATETIME2,status VARCHAR(20) NOT NULL DEFAULT 'IN_PROGRESS',violation_count INT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX uq_open_attempt ON test_attempt(test_id,student_id) WHERE status='IN_PROGRESS';
CREATE TABLE test_answer(attempt_id INT REFERENCES test_attempt(attempt_id),question_id INT REFERENCES test_question(question_id),answer_text NVARCHAR(MAX),file_id INT REFERENCES file_asset(file_id),points_awarded DECIMAL(8,2),feedback NVARCHAR(MAX),PRIMARY KEY(attempt_id,question_id));
ALTER TABLE assessment_score ADD CONSTRAINT fk_score_attempt FOREIGN KEY(attempt_id) REFERENCES test_attempt(attempt_id);
CREATE UNIQUE INDEX uq_score_attempt ON assessment_score(attempt_id,metric_code) WHERE attempt_id IS NOT NULL;
CREATE TABLE audit_log(audit_id INT IDENTITY PRIMARY KEY,actor_id INT REFERENCES account(account_id),action VARCHAR(60) NOT NULL,entity_type VARCHAR(50),entity_id INT,summary NVARCHAR(1000),created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE security_event(security_id INT IDENTITY PRIMARY KEY,account_id INT REFERENCES account(account_id),attempt_id INT REFERENCES test_attempt(attempt_id),event_type VARCHAR(50) NOT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE maintenance_run(run_key VARCHAR(60) PRIMARY KEY,status VARCHAR(15) NOT NULL,details NVARCHAR(1000),created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX ix_enrollment_student ON enrollment(student_id,status);
CREATE INDEX ix_enrollment_class ON enrollment(class_id,status);
CREATE INDEX ix_event_time ON schedule_event(starts_at,owner_id);
CREATE INDEX ix_outbox_queue ON email_outbox(status,next_attempt_at);
CREATE INDEX ix_attempt_student ON test_attempt(student_id,started_at);
CREATE INDEX ix_score_student ON assessment_score(student_id,metric_code,assessment_date);

CREATE UNIQUE INDEX uq_score_submission ON assessment_score(submission_id) WHERE submission_id IS NOT NULL;
CREATE UNIQUE INDEX uq_event_assignment ON schedule_event(assignment_id) WHERE assignment_id IS NOT NULL;
